      padding: 24px;
      display: flex;
      flex-direction: column;
      gap: 24px;
    }

    .empty-state {
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      background: var(--surface);
      padding: 32px;
      text-align: center;
    }

    .empty-state h2 {
      margin: 0 0 8px;
      color: var(--heading);
      font-size: 18px;
      font-weight: 500;
    }

    .empty-state p {
      margin: 0;
      color: var(--text-muted);
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
      gap: 12px;
    }

    .stat-card {
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      background: var(--surface);
      padding: 16px;
      display: flex;
      flex-direction: column;
      gap: 6px;
      min-height: 96px;
    }

    .stat-label {
      color: var(--text-muted);
      font-size: 12px;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    .stat-value {
      color: var(--heading);
      font-size: 28px;
      font-weight: 600;
      line-height: 1.1;
    }

    .tone-pass .stat-value,
    .text-pass { color: var(--pass); }
    .tone-warn .stat-value,
    .text-warn { color: var(--warn); }
    .tone-fail .stat-value,
    .text-fail { color: var(--fail); }

    .section {
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .section-heading {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      gap: 12px;
      flex-wrap: wrap;
    }

    .section-heading h2 {
      margin: 0;
      color: var(--heading);
      font-size: 20px;
      font-weight: 600;
    }

    .section-heading p {
      margin: 0;
      color: var(--text-muted);
    }

    .table-wrap {
      overflow-x: auto;
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      background: var(--surface);
    }

    table {
      width: 100%;
      border-collapse: collapse;
      font-size: 14px;
    }

    thead {
      border-bottom: 1px solid var(--border);
      background: var(--surface-muted);
    }

    th {
      padding: 12px 16px;
      text-align: left;
      font-weight: 500;
      color: var(--text-muted);
      white-space: nowrap;
    }

    td {
      padding: 12px 16px;
      border-top: 1px solid rgba(31, 41, 55, 0.5);
      vertical-align: top;
    }

    tbody tr {
      transition: background-color 120ms ease;
    }

    tbody tr:hover {
      background: var(--surface-hover);
    }

    .sortable {
      cursor: pointer;
      user-select: none;
    }

    .sortable:hover {
      color: var(--text);
    }

    .table-num {
      text-align: right;
      color: var(--text);
      white-space: nowrap;
    }

    .table-muted {
      color: var(--text-muted);
    }

    .id-cell {
      font-weight: 500;
      color: var(--heading);
    }

    .status-pill {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      padding: 2px 8px;
      border-radius: 999px;
      border: 1px solid var(--border);
      background: rgba(17, 24, 39, 0.6);
      color: var(--text);
      font-size: 12px;
      white-space: nowrap;
    }

    .status-dot {
      width: 8px;
      height: 8px;
      border-radius: 999px;
      background: var(--text-subtle);
    }

    .status-pass .status-dot { background: var(--pass); }
    .status-fail .status-dot { background: var(--fail); }
    .status-error .status-dot { background: var(--warn); }

    .pass-rate-track {
      width: 80px;
      height: 20px;
      overflow: hidden;
      border-radius: 999px;
      background: var(--track);
      position: relative;
      border: 1px solid rgba(31, 41, 55, 0.8);
    }

    .pass-rate-fill {
      position: absolute;
      inset: 0 auto 0 0;
      background: var(--pill-gradient);
      border-radius: 999px;
    }

    .pass-rate-label {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 12px;
      font-weight: 600;
      color: #ffffff;
      white-space: nowrap;
      z-index: 1;
    }

    .histogram {
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      background: var(--surface);
      padding: 16px;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .hist-row {
      display: grid;
      grid-template-columns: 72px 1fr 40px;
      gap: 12px;
      align-items: center;
    }

    .hist-label,
    .hist-count {
      color: var(--text-muted);
      font-size: 12px;
    }

    .hist-bar-track {
      height: 16px;
      border-radius: 999px;
      background: var(--track);
      overflow: hidden;
    }

    .hist-bar-fill {
      height: 100%;
      border-radius: 999px;
      background: var(--pill-gradient);
    }

    .filter-bar {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      align-items: center;
    }

    .filter-input,
    .filter-select {
      border: 1px solid #374151;
      border-radius: var(--radius-md);
      background: var(--canvas);
      color: var(--text);
      padding: 8px 10px;
    }

    .filter-input::placeholder {
      color: var(--text-subtle);
    }

    .filter-input:focus,
    .filter-select:focus {
      outline: none;
      border-color: var(--accent);
      box-shadow: 0 0 0 1px var(--accent);
    }

    .filter-input {
      min-width: 260px;
      flex: 1 1 260px;
    }

    .filter-count {
      margin-left: auto;
      color: var(--text-muted);
      font-size: 12px;
    }

    .group-list {
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .group-card {
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      overflow: hidden;
      background: var(--surface);
    }

    .group-header {
      padding: 16px;
      border-bottom: 1px solid var(--border);
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 12px;
      flex-wrap: wrap;
      background: rgba(17, 24, 39, 0.65);
    }

    .group-title-wrap {
      display: flex;
      flex-direction: column;
      gap: 4px;
    }

    .group-title {
      margin: 0;
      color: var(--heading);
      font-size: 18px;
      font-weight: 600;
    }

    .group-subtitle {
      margin: 0;
      color: var(--text-muted);
      font-size: 13px;
    }

    .group-metrics {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 10px 14px;
    }

    .metric {
      display: flex;
      flex-direction: column;
      gap: 2px;
    }

    .metric-label {
      color: var(--text-muted);
      font-size: 12px;
    }

    .metric-value {
      color: var(--heading);
      font-weight: 500;
    }

    .test-row {
      cursor: pointer;
    }

    .expand-cell {
      width: 40px;
      color: var(--text-muted);
      text-align: center;
    }

    .detail-row td {
      padding: 0;
      background: rgba(3, 7, 18, 0.5);
    }

    .detail-panel {
      padding: 16px;
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    .detail-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 16px;
    }

    .detail-card,
    .assertion-card,
    .error-card {
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      background: var(--surface);
      padding: 16px;
    }

    .detail-card h4,
    .assertion-card h4,
    .error-card h4 {
      margin: 0 0 10px;
      color: var(--heading);
      font-size: 14px;
      font-weight: 500;
    }

    pre {
      margin: 0;
      white-space: pre-wrap;
      word-break: break-word;
      font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
      font-size: 12px;
      color: var(--text);
      max-height: 320px;
      overflow: auto;
    }

    .evaluator-table-wrap {
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      overflow-x: auto;
      background: var(--surface);
    }

    .evaluator-table-wrap th,
    .evaluator-table-wrap td {
      padding: 14px 20px;
    }

    .assertion-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 16px;
    }

    .assertion-list {
      list-style: none;
      margin: 0;
      padding: 0;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .assertion-item {
      border: 1px solid rgba(31, 41, 55, 0.8);
      border-radius: var(--radius-md);
      background: rgba(3, 7, 18, 0.45);
      padding: 10px 12px;
      display: flex;
      flex-direction: column;
      gap: 8px;
    }

    .assertion-topline {
      display: flex;
      align-items: center;
      flex-wrap: wrap;
      gap: 8px;
    }

    .assertion-badge {
      border: 1px solid rgba(8, 145, 178, 0.45);
      background: rgba(8, 145, 178, 0.16);
      color: #67e8f9;
      border-radius: var(--radius-md);
      padding: 2px 8px;
      font-size: 12px;
      font-weight: 500;
      align-self: flex-start;
    }

    .assertion-status {
      font-size: 12px;
      font-weight: 500;
    }

    .assertion-text {
      color: var(--text);
    }

    .assertion-evidence {
      color: var(--text-muted);
      font-size: 12px;
      white-space: pre-wrap;
      word-break: break-word;
    }

    .meta-row {
      display: flex;
      flex-wrap: wrap;
      gap: 8px 16px;
      color: var(--text-muted);
      font-size: 12px;
      border-top: 1px solid var(--border);
      padding-top: 12px;
    }

    .error-card {
      border-color: rgba(248, 113, 113, 0.45);
      background: rgba(127, 29, 29, 0.18);
    }

    .error-card h4,
    .error-card pre {
      color: #fecaca;
    }

    .muted {
      color: var(--text-muted);
    }

    .hidden {
      display: none;
    }

    .theme-toggle {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      color: var(--text-muted);
      cursor: pointer;
      padding: 6px 10px;
      font-size: 13px;
      transition: color 120ms ease, border-color 120ms ease;
      white-space: nowrap;
    }

    .theme-toggle:hover {
      color: var(--text);
      border-color: var(--text-muted);
    }

    .criteria-cell {
      color: var(--text-muted);
      font-size: 13px;
      max-width: 320px;
    }

    .io-toggle {
      cursor: pointer;
      user-select: none;
      color: var(--text-muted);
      font-size: 13px;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      background: var(--surface);
      padding: 8px 12px;
      display: inline-flex;
      align-items: center;
      gap: 6px;
    }

    .io-toggle:hover {
      color: var(--text);
    }

    .io-toggle[open] > summary {
      margin-bottom: 12px;
    }

    .io-toggle > summary {
      list-style: none;
    }

    .io-toggle > summary::-webkit-details-marker {
      display: none;
    }

    @media (max-width: 900px) {
      .header,
      .group-header,
      .section-heading {
        align-items: flex-start;
      }

      .filter-count {
        width: 100%;
        margin-left: 0;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        transition: none !important;
        scroll-behavior: auto !important;
      }
    }
