  record: ResultManifestRecord,
  kind: 'transcript' | 'answer',
): ResolvedArtifactPointer {
  const directPath =
    kind === 'transcript'
      ? (record.transcript_path ?? record.artifacts?.transcript_path)
      : (record.answer_path ?? record.artifacts?.answer_path ?? record.output_path);
  if (directPath) {
