          passed: false,
          evidence:
            toolCalls.length > 0
              ? `Observed ${toolCalls.length} tool call(s), but none read ${file}`
              : 'No tool calls recorded',
        };
  });

  const passed = assertions.filter((assertion) => assertion.passed).length;
  return {
    score: passed / assertions.length,
    assertions,
  };
