      repo: `file://${remoteDir}`,
      path: cloneDir,
      autoPush: true,
    });
    await maybeAutoExportRunArtifacts(payload(projectDir, runDir));
    const warnSpy = spyOn(console, 'warn').mockImplementation(() => {});

    try {
