  if (!resolved.absolutePath) return { error: resolved.error };

  let realBase: string;
  let realArtifact: string;
  try {
    realBase = realpathSync(baseDir);
    realArtifact = realpathSync(resolved.absolutePath);
  } catch {
    return {};
